const setRideShared = `-- name: SetRideShared :execrows
update rides
set shared_at = case when $1::boolean then coalesce(shared_at, now()) else null end
where id = $2 and user_id = $3
`

type SetRideSharedParams struct {
	Shared bool
	ID     pgtype.UUID
	UserID pgtype.UUID
}

// Per-ride opt-in (WATTROOM.md privacy): the owner flips it, the timestamp
// remembers when; unsharing clears it. Owner-only by the where clause.
func (q *Queries) SetRideShared(ctx context.Context, arg SetRideSharedParams) (int64, error) {
	result, err := q.db.Exec(ctx, setRideShared, arg.Shared, arg.ID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const startRideExport = `-- name: StartRideExport :exec
insert into ride_exports (ride_id, destination, state, attempts, updated_at)
values ($1, $2, 'pending', 0, now())
on conflict (ride_id, destination) do update
    set state = 'pending', updated_at = now()
    where ride_exports.state <> 'delivered'
`

type StartRideExportParams struct {
	RideID      pgtype.UUID
	Destination string
}

// Opens (or re-opens) the delivery record for one ride and destination. A
// retry lands on the same row: one delivery per pair, ever (#799).
func (q *Queries) StartRideExport(ctx context.Context, arg StartRideExportParams) error {
	_, err := q.db.Exec(ctx, startRideExport, arg.RideID, arg.Destination)
	return err
}

